import json, subprocess, warnings
warnings.filterwarnings("ignore")
from TTS.utils.synthesizer import Synthesizer
lines = [
 "बच्चे की प्लानिंग कर रही हैं? और किसी ने कहा, ए एम एच टेस्ट करवाओ? घबराइए मत. आज जानिए ए एम एच टेस्ट क्या बताता है, और क्या नहीं. आखिर तक देखिए.",
 "ए एम एच यानी एंटी मुलेरियन हार्मोन. यह अंडाशय की छोटी छोटी थैलियों से बनता है. यह बताता है कि अंडाशय में लगभग कितने अंडे बचे हैं. इसे ओवेरियन रिज़र्व कहते हैं. इसे अंडों का बैंक बैलेंस समझिए.",
 "हर महिला के अंडों की संख्या उम्र के साथ धीरे धीरे कम होती है. इसलिए ए एम एच भी उम्र के साथ घटता है. पैंतीस के बाद यह गिरावट ज़्यादा तेज़ होती है.",
 "सबसे बड़ा मिथक. ए एम एच कम है, तो बच्चा नहीं होगा? नहीं! ए एम एच अंडों की संख्या बताता है, उनकी क्वालिटी नहीं. एक बड़ी रिसर्च में, तीस से चौवालीस साल की महिलाओं में, कम ए एम एच वाली महिलाएं भी, उतनी ही आसानी से नैचुरल प्रेग्नेंट हुईं.",
 "तो यह टेस्ट कब काम आता है? आई वी एफ की प्लानिंग में, दवाओं का असर कितना होगा, यह समझने के लिए. पी सी ओ एस में, जहां ए एम एच अक्सर ज़्यादा होता है. एग फ्रीज़िंग, या देर से परिवार की प्लानिंग में. और अंडाशय की सर्जरी या कीमोथेरेपी के बाद. हमेशा डॉक्टर की सलाह से.",
 "टेस्ट बहुत आसान है, बस एक खून का सैंपल. पीरियड्स के किसी भी दिन करा सकते हैं. अगर आप गर्भनिरोधक गोलियां लेती हैं, तो डॉक्टर को ज़रूर बताएं, क्योंकि इनसे ए एम एच कम आ सकता है.",
 "रिपोर्ट कैसे समझें? कम, यानी अंडे कम बचे हैं. फर्टिलिटी डॉक्टर से मिलें, पर उम्मीद न छोड़ें. उम्र के हिसाब से सामान्य, अच्छी बात. ज़्यादा, तो कभी कभी पी सी ओ एस का संकेत. याद रखें, सामान्य रेंज उम्र और लैब के हिसाब से बदलती है.",
 "कुछ ज़रूरी बातें. ए एम एच अकेले फैसला नहीं करता. डॉक्टर उम्र, अल्ट्रासाउंड, और दूसरे हार्मोन के साथ देखते हैं. और प्रेग्नेंसी में दोनों पार्टनर ज़रूरी हैं, पुरुषों के लिए सीमेन टेस्ट होता है.",
 "याद रखें, कोई भी दवा सिर्फ डॉक्टर की सलाह से ही लें. क्या आपने कभी ए एम एच टेस्ट के बारे में सुना था? कमेंट में बताइए, और शेयर करें. और ज़्यादा जानकारी के लिए, हमारा फेसबुक पेज और यूट्यूब चैनल फॉलो करें. हेल्थ टेस्ट सिम्प्लिफाइड. ध्यान दें, यह वीडियो केवल बीमारियों और टेस्ट के बारे में सामान्य जानकारी के लिए है. जानकारी समय के साथ बदल सकती है. अपनी स्थिति को इस वीडियो से न जोड़ें. हमेशा अपने डॉक्टर से ही सलाह लें, और उन्हीं की सलाह मानें.",
]
import os
d = os.environ.get("HTS_MODEL", "/tmp/hi/hi/")
s = Synthesizer(tts_checkpoint=d + "fastpitch/best_model.pth", tts_config_path=d + "fastpitch/config.json",
                vocoder_checkpoint=d + "hifigan/best_model.pth", vocoder_config=d + "hifigan/config.json", use_cuda=False)
durs = []
for i, l in enumerate(lines):
    f = f"/tmp/amhr_{i}.wav"; s.save_wav(s.tts(l, speaker_name="female"), f)
    subprocess.run(["ffmpeg","-nostdin","-y","-loglevel","error","-i",f,"-af","rubberband=pitch=0.96:formant=preserved,equalizer=f=250:t=q:w=1:g=2,treble=g=-1.5:f=6000",f"/tmp/amh_{i}.wav"],check=True); f=f"/tmp/amh_{i}.wav"
    durs.append(float(subprocess.check_output(["ffprobe", "-v", "error", "-show_entries", "format=duration", "-of", "csv=p=0", f]).decode()))
json.dump(durs, open("/tmp/amh_durs.json", "w")); print([round(x, 1) for x in durs], round(sum(durs), 1))
